mapper.select:
SELECT t.id AS ticketId, t.ticket_no AS ticketNo, si.title AS showTitle, ss.session_name AS sessionName, ss.session_time AS sessionTime, tc.name AS categoryName, t.price AS price, t.status AS status, t.check_time AS checkTime FROM ticket t LEFT JOIN show_session ss ON ss.id = t.session_id LEFT JOIN show_info si ON si.id = ss.show_id LEFT JOIN ticket_category tc ON tc.id = t.category_id WHERE t.user_id = #{userId}
AND t.status = #{status}
ORDER BY t.id DESC
